import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Development Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/development/index.md","filePath":"en/development/index.md","lastUpdated":1769206051000}`),a={name:`en/development/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="development-guide" tabindex="-1">Development Guide <a class="header-anchor" href="#development-guide" aria-label="Permalink to “Development Guide”">​</a></h1><h2 id="compilation-documentation" tabindex="-1">Compilation Documentation <a class="header-anchor" href="#compilation-documentation" aria-label="Permalink to “Compilation Documentation”">​</a></h2><p>Xray supports a wide range of platforms, allowing you to perform cross-compilation on various systems yourself.</p><p>Please click <a href="./intro/compile.html">Compilation Documentation</a> to view specific compilation-related content.</p><h2 id="design-philosophy" tabindex="-1">Design Philosophy <a class="header-anchor" href="#design-philosophy" aria-label="Permalink to “Design Philosophy”">​</a></h2><p>The Xray kernel provides a platform upon which secondary development can be conducted.</p><p>This chapter expounds on Xray&#39;s design goals and architecture.</p><p>Please click <a href="./intro/design.html">Design Philosophy</a> to understand Xray&#39;s design goals and architecture.</p><h2 id="development-guidelines" tabindex="-1">Development Guidelines <a class="header-anchor" href="#development-guidelines" aria-label="Permalink to “Development Guidelines”">​</a></h2><p>This chapter explains the guidelines to follow during the process of obtaining code, conducting development, and submitting PRs, as well as relevant coding conventions.</p><p>Please click <a href="./intro/guide.html">Development Guidelines</a> to view the criteria to be followed in Xray development.</p><h2 id="protocol-details" tabindex="-1">Protocol Details <a class="header-anchor" href="#protocol-details" aria-label="Permalink to “Protocol Details”">​</a></h2><p>Xray utilizes many types of protocols. You can obtain detailed descriptions of these protocols through various channels.</p><h3 id="vless-protocol" tabindex="-1"><a href="./protocols/vless.html">VLESS Protocol</a> <a class="header-anchor" href="#vless-protocol" aria-label="Permalink to “VLESS Protocol”">​</a></h3><p>VLESS is a stateless lightweight transport protocol that can serve as a bridge between Xray clients and servers.</p><h3 id="vmess-protocol" tabindex="-1"><a href="./protocols/vmess.html">VMess Protocol</a> <a class="header-anchor" href="#vmess-protocol" aria-label="Permalink to “VMess Protocol”">​</a></h3><p>VMess is an encrypted transport protocol that can serve as a bridge between Xray clients and servers.</p><h3 id="mux-cool-protocol" tabindex="-1"><a href="./protocols/muxcool.html">Mux.Cool Protocol</a> <a class="header-anchor" href="#mux-cool-protocol" aria-label="Permalink to “Mux.Cool Protocol”">​</a></h3><p>The Mux.Cool protocol is a multiplexing transport protocol used to transmit multiple independent data streams within a single established data stream.</p><h3 id="mkcp-protocol" tabindex="-1"><a href="./protocols/mkcp.html">mKCP Protocol</a> <a class="header-anchor" href="#mkcp-protocol" aria-label="Permalink to “mKCP Protocol”">​</a></h3><p>mKCP is a stream transport protocol, modified from the <a href="https://github.com/skywind3000/kcp" target="_blank" rel="noreferrer">KCP Protocol</a>, capable of transmitting arbitrary data streams in order.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};